void Solver::bump_var(int var, double coeff) {
    constexpr double LIMIT   = 1e100;
    constexpr double RESCALE = 1e-100;

    if (coeff == 0.0) return;                     // nothing to bump

    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;

    if (newAct > LIMIT) {
        // Rescale all variable activities and the increment factor
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= RESCALE;
        }
        var_inc *= RESCALE;
    }

    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
